            delta = rng.uniform(-T, T)
            new_x = x + delta
            for i in range(dim):
                if new_x[i] < lb: new_x[i] = lb
                elif new_x[i] > ub: new_x[i] = ub
            f_new = func(new_x)
            f_old = func(x)
            if f_new <= f_old:
                x = np.copy(new_x)
